```spl
index=web_proxy sourcetype=apache:access host="web-proxy-01"
| where match(_raw, "(?i)\$\{jndi:(ldap|rmi|dns|nis|iiop):")
| stats count min(_time) as first_seen max(_time) as last_seen by src_ip, uri, status, useragent
```
```elasticsearch
GET /logs-security-*/_search
{
  "query": {
    "bool": {
      "must": [
        { "term": { "asset_id": "SRV-WEB-001" } },
        { "query_string": { "query": "*jndi* OR *ldap*" } }
      ]
    }
  }
}
```
